{"kind": "content", "icon": "📚", "head": "पं. विष्णु नारायण भातखंडे (1860–1936)", "points": ["मुंबई में जन्म, पेशे से वकील", "पूरे भारत घूमकर बंदिशें इकट्ठी कीं", "10 थाट पद्धति", "भातखंडे स्वरलिपि", "'हिंदुस्तानी संगीत पद्धति', 'क्रमिक पुस्तक मालिका'; लखनऊ में मैरिस कॉलेज (अब भातखंडे विश्वविद्यालय)"], "say": "पंडित विष्णु नारायण भातखंडे का जन्म अठारह सौ साठ में मुंबई में हुआ। वे पेशे से वकील थे, पर संगीत उनका जुनून था। उन्होंने पूरे भारत की यात्रा की, बड़े उस्तादों से मिले, और हज़ारों बंदिशें इकट्ठी करके लिखीं, जो पहले केवल गुरुओं के पास थीं। उन्होंने रागों को दस थाटों में बाँटा और स्वर लिखने की सरल पद्धति बनाई, जो आज भातखंडे स्वरलिपि कहलाती है। उनकी किताबें क्रमिक पुस्तक मालिका आज भी पढ़ाई जाती हैं। लखनऊ में उनका स्थापित कॉलेज आज भातखंडे संस्कृति विश्वविद्यालय है।"},
{"kind": "content", "icon": "🎓", "head": "पं. विष्णु दिगंबर पलुस्कर (1872–1931)", "points": ["महाराष्ट्र के कुरुंदवाड में जन्म", "बचपन में आँखों की चोट", "1901 – लाहौर में गांधर्व महाविद्यालय", "संगीत को आम लोगों तक पहुँचाया", "'रघुपति राघव राजा राम' की प्रसिद्ध धुन; पलुस्कर स्वरलिपि"], "say": "पंडित विष्णु दिगंबर पलुस्कर का जन्म अठारह सौ बहत्तर में महाराष्ट्र में हुआ। बचपन में एक दुर्घटना में उनकी आँखों को चोट लगी, जिससे दृष्टि कमज़ोर हो गई, तब उन्होंने संगीत को जीवन बना लिया। उस समय संगीत को अच्छी नज़र से नहीं देखा जाता था। उन्होंने उन्नीस सौ एक में लाहौर में गांधर्व महाविद्यालय खोला, ताकि आम परिवारों के बच्चे सम्मान से संगीत सीख सकें। गांधी जी का प्रिय भजन रघुपति राघव राजा राम की प्रसिद्ध धुन उन्हीं की है। उन्होंने भी एक स्वरलिपि बनाई।"},
{"kind": "content", "icon": "🎤", "head": "लता मंगेशकर (1929–2022)", "points": ["इंदौर में जन्म", "'स्वर कोकिला', 'भारत की आवाज़'", "36 से ज़्यादा भाषाओं में हज़ारों गीत", "'ऐ मेरे वतन के लोगो' (1963)", "भारत रत्न (2001), दादासाहेब फाल्के पुरस्कार"], "say": "लता मंगेशकर का जन्म उन्नीस सौ उनतीस में इंदौर में हुआ। उनके पिता दीनानाथ मंगेशकर भी गायक थे। पिता के जल्दी निधन के बाद तेरह साल की उम्र से ही उन्होंने परिवार चलाने के लिए गाना शुरू किया। उन्होंने छत्तीस से ज़्यादा भाषाओं में हज़ारों गीत गाए। उन्नीस सौ तिरसठ में उनका गाया ऐ मेरे वतन के लोगो सुनकर प्रधानमंत्री नेहरू की आँखें भर आईं। उन्हें स्वर कोकिला कहा गया, और दो हज़ार एक में भारत रत्न मिला। दो हज़ार बाईस में उनका निधन हुआ।"},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "दस थाट पद्धति किसने दी?", "a": "पं. विष्णु नारायण भातखंडे", "pause": 4, "say": "सोचिए, दस थाट पद्धति किसने दी? ... पंडित विष्णु नारायण भातखंडे।"},
{"kind": "content", "icon": "🪕", "head": "पं. रविशंकर (1920–2012)", "points": ["वाराणसी में जन्म", "गुरु – बाबा अलाउद्दीन ख़ाँ (मैहर)", "सितार को विश्व में पहचान", "बीटल्स के जॉर्ज हैरिसन को सिखाया", "भारत रत्न (1999), ग्रैमी पुरस्कार"], "say": "पंडित रविशंकर का जन्म उन्नीस सौ बीस में वाराणसी में हुआ। बचपन में वे अपने बड़े भाई उदय शंकर के नृत्य दल के साथ यूरोप घूमे। फिर उन्होंने मैहर में बाबा अलाउद्दीन ख़ाँ से कई साल कठोर साधना करके सितार सीखा। उन्होंने सितार को पूरी दुनिया में पहचान दिलाई, पश्चिम के बड़े संगीतकारों के साथ काम किया, और प्रसिद्ध बैंड बीटल्स के जॉर्ज हैरिसन को सितार सिखाया। उन्हें उन्नीस सौ निन्यानबे में भारत रत्न और कई ग्रैमी पुरस्कार मिले।"},
{"kind": "content", "icon": "🌟", "head": "भारत रत्न पाने वाले संगीतकार", "points": ["एम. एस. सुब्बुलक्ष्मी (1998) – पहली संगीतकार", "पं. रविशंकर (1999)", "लता मंगेशकर, बिस्मिल्लाह ख़ाँ (2001)", "पं. भीमसेन जोशी (2009)", "भूपेन हज़ारिका (2019, मरणोपरांत)"], "say": "संगीत के क्षेत्र में कई महान कलाकारों को भारत रत्न मिला है। कर्नाटक संगीत की एम एस सुब्बुलक्ष्मी, उन्नीस सौ अट्ठानबे में, भारत रत्न पाने वाली पहली संगीतकार थीं। फिर पंडित रविशंकर, उन्नीस सौ निन्यानबे में। लता मंगेशकर और हमारे बिहार के बिस्मिल्लाह ख़ाँ, दोनों को दो हज़ार एक में। पंडित भीमसेन जोशी को दो हज़ार नौ में। और असम के गायक संगीतकार भूपेन हज़ारिका को दो हज़ार उन्नीस में, मरणोपरांत। यह सूची परीक्षा के लिए याद रखिए।"},
